package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreReplayDecisionTest {

	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void producerChecksSurviveConcurrentDecisionRetirement(@TempDir File directory) throws Exception {
		ValueStore values = new ValueStore(directory, new LmdbStoreConfig().setInlineLiterals(true));
		try {
			Literal value = SimpleValueFactory.getInstance().createLiteral(7);
			long id = values.storeValue(value);
			TxnReplayPolicy.Decision decision = new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false,
					0, 0, 0);
			CountDownLatch start = new CountDownLatch(1);
			var executor = Executors.newFixedThreadPool(2);
			try {
				var consumer = executor.submit(() -> {
					assertTrue(start.await(5, TimeUnit.SECONDS));
					for (int i = 0; i < 1_000_000; i++) {
						values.setReplayDecision(decision);
						values.clearReplayDecision(decision);
					}
					return null;
				});
				var producer = executor.submit(() -> {
					assertTrue(start.await(5, TimeUnit.SECONDS));
					for (int i = 0; i < 1_000_000; i++) {
						assertEquals(id, values.storeValue(value));
					}
					return null;
				});
				start.countDown();
				producer.get(10, TimeUnit.SECONDS);
				consumer.get(10, TimeUnit.SECONDS);
			} finally {
				executor.shutdownNow();
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
			}
		} finally {
			values.close();
		}
	}

	@Test
	void failedDecisionRemainsAuthoritativeUntilRollback(@TempDir File directory) throws Exception {
		ValueStore values = new ValueStore(directory, new LmdbStoreConfig());
		try {
			TxnReplayPolicy.Decision decision = new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false,
					0, 0, 0);
			values.setReplayDecision(decision);
			LmdbTransactionRetryException failure = decision.capacityFailure("ValueStore", new IOException("capacity"));
			values.clearReplayDecision(decision);
			Literal value = SimpleValueFactory.getInstance().createLiteral(7);
			assertSame(failure, assertThrows(LmdbTransactionRetryException.class, () -> values.storeValue(value)));
			values.rollback();
			assertTrue(values.storeValue(value) != 0);
		} finally {
			values.close();
		}
	}
}
